'use server';

import { revalidateTag } from 'next/cache';

interface PostData {
  title: string;
  content: string;
}

// Mock database - in a real app this would be a database connection
let posts: PostData[] = [
  { title: 'First Post', content: 'This is the first post content' },
  { title: 'Second Post', content: 'This is the second post content' }
];

export async function createPost(data: PostData): Promise<PostData> {
  // Simulate database save with delay
  await new Promise(resolve => setTimeout(resolve, 100));

  const newPost = {
    ...data,
    id: Date.now().toString()
  };

  // Add to mock database
  posts.push(newPost);

  // Invalidate the 'posts' cache tag to ensure fresh data is fetched
  // This guarantees no stale content is served on the next page load
  revalidateTag('posts');

  return newPost;
}

// Helper function to get all posts with cache tag
export async function getPosts(): Promise<PostData[]> {
  // Simulate database fetch with delay
  await new Promise(resolve => setTimeout(resolve, 100));

  return posts;
}

